function listPosts({url,$}) { const posts=[]; $('item,entry').each((_,e)=>{const n=$(e);let link=n.children('link').filter((_,a)=>!$(a).attr('rel')||$(a).attr('rel')==='alternate').first();const u=link.attr('href')||link.text().trim(); if(u) posts.push({url:u,title:n.children('title').text().trim(),publishedAt:n.children('pubDate,published,updated').first().text().trim()});});return {posts,next:null}; }
function parsePost({url,$}) {
 const title=$("h1.post-title").first().text().trim(); const body=$(".post-body").first().clone();
  body.find('script,style,noscript').remove();
 let ld={}; $('script[type="application/ld+json"]').each((_,e)=>{try{const v=JSON.parse($(e).text());const walk=x=>{if(Array.isArray(x))x.forEach(walk);else if(x&&typeof x==='object'){if(/Article|Posting/i.test(String(x['@type']||'')))ld=x;if(x['@graph'])walk(x['@graph']);}};walk(v);}catch{}});
 const author=$('meta[name="author"]').attr('content')||$('a[rel="author"],.article-author,.gh-author-name,.author-name').first().text().trim()||(typeof ld.author==='string'?ld.author:Array.isArray(ld.author)?ld.author.map(a=>a.name).join(', '):ld.author?.name)||null;
 const dateText=$('.post-timestamp').first().text().match(/(\d{4})年(\d{1,2})月(\d{1,2})日/); const publishedAt=(dateText?dateText[1]+'-'+dateText[2].padStart(2,'0')+'-'+dateText[3].padStart(2,'0'):null)||$('meta[property="article:published_time"],meta[itemprop="datePublished"]').first().attr('content')||$('time[datetime]').first().attr('datetime')||ld.datePublished||null;
 const tags=Array.isArray(ld.keywords)?ld.keywords:$('a[rel="tag"],.post-tags a,.article-tags a,.tags a,a[href^="/tags/"]').map((_,e)=>$(e).text().trim().replace(/^#/, '')).get();
 return {title,bodyHtml:body.html()||'',author,publishedAt,tags};
}
